<?php
require __DIR__ . '/../app/bootstrap.php'; require_login();
$tenant=(int)($_GET['inquilino_id']??0); $year=(int)($_GET['anio']??date('Y')); $from=$_GET['desde']??''; $to=$_GET['hasta']??'';
$where=[];$args=[];
if($tenant){$where[]='inquilino_id=?';$args[]=$tenant;}
if($year>0){$where[]='YEAR(fecha)=?';$args[]=$year;}
if($from!==''){$where[]='fecha>=?';$args[]=$from;}
if($to!==''){$where[]='fecha<=?';$args[]=$to;}
$filter=$where?' WHERE '.implode(' AND ',$where):'';
function sums(PDO $pdo,string $table,string $filter,array $args): array { $s=$pdo->prepare("SELECT COALESCE(SUM(importe),0) total,COUNT(*) n FROM $table $filter");$s->execute($args);return $s->fetch(); }
$c=sums($pdo,'cargos',$filter,$args);$i=sums($pdo,'ingresos',$filter,$args);$balance=(float)$i['total']-(float)$c['total'];$rent=(float)$c['total']>0?(float)$i['total']/(float)$c['total']*100:0;
$tenants=$pdo->query('SELECT id,nombre FROM inquilinos ORDER BY nombre')->fetchAll();
$types=$pdo->prepare("SELECT tipo,COUNT(*) n,SUM(importe) total FROM cargos $filter GROUP BY tipo ORDER BY total DESC");$types->execute($args);$types=$types->fetchAll();
$methods=$pdo->prepare("SELECT metodo,COUNT(*) n,SUM(importe) total FROM ingresos $filter GROUP BY metodo ORDER BY total DESC");$methods->execute($args);$methods=$methods->fetchAll();
$byTenant=$pdo->prepare("SELECT t.id,t.nombre,COALESCE(c.total,0) cargos,COALESCE(i.total,0) ingresos,COALESCE(i.total,0)-COALESCE(c.total,0) balance FROM inquilinos t LEFT JOIN (SELECT inquilino_id,SUM(importe) total FROM cargos GROUP BY inquilino_id) c ON c.inquilino_id=t.id LEFT JOIN (SELECT inquilino_id,SUM(importe) total FROM ingresos GROUP BY inquilino_id) i ON i.inquilino_id=t.id ".($tenant?' WHERE t.id=?':'')." ORDER BY balance ASC");$byTenant->execute($tenant?[$tenant]:[]);$byTenant=$byTenant->fetchAll();
$monthly=$pdo->query("SELECT m.mes,COALESCE(c.total,0) cargos,COALESCE(i.total,0) ingresos FROM (SELECT DATE_FORMAT(DATE_SUB(CURDATE(),INTERVAL n MONTH),'%Y-%m') mes FROM (SELECT 0 n UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10 UNION SELECT 11 UNION SELECT 12 UNION SELECT 13 UNION SELECT 14 UNION SELECT 15 UNION SELECT 16 UNION SELECT 17 UNION SELECT 18 UNION SELECT 19 UNION SELECT 20 UNION SELECT 21 UNION SELECT 22 UNION SELECT 23) nums) m LEFT JOIN (SELECT DATE_FORMAT(fecha,'%Y-%m') mes,SUM(importe) total FROM cargos GROUP BY mes) c ON c.mes=m.mes LEFT JOIN (SELECT DATE_FORMAT(fecha,'%Y-%m') mes,SUM(importe) total FROM ingresos GROUP BY mes) i ON i.mes=m.mes ORDER BY m.mes")->fetchAll();
$annual=$pdo->query("SELECT y.anio,COALESCE(c.alquiler,0) alquiler,COALESCE(c.total,0) cargos,COALESCE(i.total,0) ingresos,COALESCE(i.total,0)-COALESCE(c.total,0) balance FROM (SELECT YEAR(fecha) anio FROM cargos UNION SELECT YEAR(fecha) FROM ingresos) y LEFT JOIN (SELECT YEAR(fecha) anio,SUM(importe) total,SUM(CASE WHEN tipo='Alquiler' THEN importe ELSE 0 END) alquiler FROM cargos GROUP BY YEAR(fecha)) c ON c.anio=y.anio LEFT JOIN (SELECT YEAR(fecha) anio,SUM(importe) total FROM ingresos GROUP BY YEAR(fecha)) i ON i.anio=y.anio ORDER BY y.anio DESC")->fetchAll();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Estadísticas · APP Alquileres</title><link rel="stylesheet" href="assets/app.css"></head><body><header class="topbar"><a class="brand" href="index.php"><span class="brand-icon">⌂</span><span>APP Alquileres<small>Estadísticas</small></span></a><a class="btn outline" href="index.php">Volver al inicio</a></header><main class="content"><div class="page-head"><div><h1>Estadísticas</h1><p class="muted">Filtra por inquilino, año y rango de fechas.</p></div></div><section class="panel"><form class="form-grid" method="get"><div><label>Inquilino</label><select name="inquilino_id"><option value="0">Todos</option><?php foreach($tenants as $t):?><option value="<?=$t['id']?>" <?=$tenant===$t['id']?'selected':''?>><?=e($t['nombre'])?></option><?php endforeach;?></select></div><div><label>Año (0 = todos)</label><input type="number" name="anio" value="<?=$year?>"></div><div><label>Desde</label><input type="date" name="desde" value="<?=e($from)?>"></div><div><label>Hasta</label><input type="date" name="hasta" value="<?=e($to)?>"></div><div class="full"><button class="btn primary">Aplicar filtros</button></div></form></section><div class="kpis"><div class="kpi"><span>Total cargos</span><strong><?=money($c['total'])?></strong></div><div class="kpi"><span>Total ingresos</span><strong class="green"><?=money($i['total'])?></strong></div><div class="kpi"><span>Balance (ingresos − cargos)</span><strong style="color:<?=$balance<0?'#c33434':'#13804a'?>"><?=money($balance)?></strong></div><div class="kpi"><span>Rentabilidad de cobro</span><strong><?=number_format($rent,1,',','.')?>%</strong></div></div><section class="panel"><h3>Cargos por tipo</h3><div class="table-wrap"><table><tr><th>Tipo</th><th>Movimientos</th><th>Total</th><th>Porcentaje</th></tr><?php foreach($types as $r):?><tr><td><?=e($r['tipo'])?></td><td><?=$r['n']?></td><td><?=money($r['total'])?></td><td><?=number_format((float)$c['total']?(float)$r['total']/(float)$c['total']*100:0,1,',','.')?>%</td></tr><?php endforeach;?></table></div></section><section class="panel"><h3>Ingresos por método</h3><div class="table-wrap"><table><tr><th>Método</th><th>Movimientos</th><th>Total</th></tr><?php foreach($methods as $r):?><tr><td><?=e($r['metodo'])?></td><td><?=$r['n']?></td><td><?=money($r['total'])?></td></tr><?php endforeach;?></table></div></section><section class="panel"><h3>Balance por inquilino</h3><div class="table-wrap"><table><tr><th>Inquilino</th><th>Cargos</th><th>Ingresos</th><th>Balance</th><th>PDF</th></tr><?php foreach($byTenant as $r):?><tr><td><?=e($r['nombre'])?></td><td><?=money($r['cargos'])?></td><td><?=money($r['ingresos'])?></td><td style="color:<?=$r['balance']<0?'#c33434':'#13804a'?>"><?=money($r['balance'])?></td><td><a href="pdf_inquilino.php?id=<?=$r['id']?>">Ver PDF</a></td></tr><?php endforeach;?></table></div></section><section class="panel"><h3>Evolución mensual (últimos 24 meses)</h3><div class="table-wrap"><table><tr><th>Mes</th><th>Cargos</th><th>Ingresos</th><th>Balance</th></tr><?php foreach($monthly as $r):?><tr><td><?=e($r['mes'])?></td><td><?=money($r['cargos'])?></td><td><?=money($r['ingresos'])?></td><td><?=money($r['ingresos']-$r['cargos'])?></td></tr><?php endforeach;?></table></div></section><section class="panel"><h3>Resumen anual</h3><div class="table-wrap"><table><tr><th>Año</th><th>Cargos alquiler</th><th>Todos los cargos</th><th>Ingresos</th><th>Balance</th></tr><?php foreach($annual as $r):?><tr><td><?=$r['anio']?></td><td><?=money($r['alquiler'])?></td><td><?=money($r['cargos'])?></td><td><?=money($r['ingresos'])?></td><td><?=money($r['balance'])?></td></tr><?php endforeach;?></table></div></section></main></body></html>
